5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.rest.function.common.FiscalYear;
7	
8	/**
9	 * The single definition of the membership points → level formula, so every place that needs an owner's
10	 * level computes it the same way and they cannot drift apart. The household size is not read off the
11	 * owner here but passed in explicitly ({@code null} for an unknown/single-member household): it depends
12	 * on other owners and is computed once by {@link OwnerHousehold}, and taking it as an argument keeps
13	 * this a pure function with no hidden reads or writes.
14	 *
15	 * <p>Shared by {@code OwnerMapper} (which exposes {@code membershipPoints} and the capped
16	 * {@code membershipLevel} on the DTO) and {@link OwnerHousehold} (which reads each other household
17	 * member's <em>raw</em> level to compute the ceiling). Kept out of the function classes because
18	 * OfficeFloor requires each function class to expose exactly one public method.
19	 */
20	public final class MembershipLevel {
21	
22	    private MembershipLevel() {
23	    }
24	
25	    /**
26	     * The owner's membership points. Starting from 0: add 2 when an email address is present, add 1
27	     * when the owner has no namesakes ({@code namesakeCount} is 0), add 2 for a household of 3 or more
28	     * members, and add 3 when the owner's tenure exceeds one fiscal year (more than one elapsed fiscal
29	     * year since the {@code registrationDate}; the fiscal year starts on 1 July).
30	     */
31	    public static int points(Owner owner, Integer householdSize) {
32	        int points = 0;
33	        if (hasEmail(owner)) {
34	            points += 2;
35	        }
36	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
37	            points += 1;
38	        }
39	        if (householdSize != null && householdSize >= 3) {
40	            points += 2;
41	        }
42	        long tenureFiscalYears = owner.getRegistrationDate() == null ? 0
43	                : FiscalYear.between(owner.getRegistrationDate(), LocalDate.now());
44	        if (tenureFiscalYears > 1) {
45	            points += 3;
46	        }
47	        return points;
48	    }
49	
50	    /**
51	     * The raw numeric level for a points total: level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for
52	     * 6 or more. This is the level before any household ceiling is applied.
53	     */
54	    public static int level(int points) {
55	        if (points <= 1) {
56	            return 1;
57	        }
58	        if (points <= 3) {
59	            return 2;
60	        }
61	        if (points <= 5) {
62	            return 3;
63	        }
64	        return 4;
65	    }
66	
67	    /** Whether the owner has a usable email address. */
68	    public static boolean hasEmail(Owner owner) {
69	        return owner.getEmail() != null && !owner.getEmail().isBlank();
70	    }
71	}
